head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF09316";
scwin.secugrpId = "";       // 증권그룹ID — init 에서 상장형 수익증권(PF) (개발 사본 fr_SecuGrpId = "PF")
scwin.isurCd = "";          // 고른 종목의 발행기관코드 — 일괄업로드 팝업에 넘긴다 (원본 vIsurCd)
scwin.SYMBL_HIDE_MKT = "2";                 // 이 시장(코스닥) 사용자는 영문종목심볼 열을 숨긴다 (원본 vSYMBL_INPUT_CD == '2')
scwin.OPEN_TYP_HIST = "H";                  // 관리 팝업 — 이력(수정)
scwin.OPEN_TYP_NEW = "N";                   // 관리 팝업 — 신규
scwin.PAGE_ID = "ULDSTF09316";              // 하위 팝업에 넘기는 호출 화면 ID (pf 계약서 §2 — 원본 05317 은 "STF09316", §10 #3)
scwin.MNG_POPUP_URL = "/ui/lst/lstproc/ULDSTF05317.xml";       // 종목명변경 관리 (원본 "//ui/…" 결함 정정, §8 #2)
scwin.UPLOAD_POPUP_URL = "/ui/lst/lstproc/ULDSTF05360.xml";    // 엑셀 일괄업로드

// 원본 : /pf/ULDSTF09316.gfm (종목변경 — 상장형 수익증권). gfm 은 저장소에 없고 W-Craft 1차 변환 + API 적용 개발 사본으로 분석했다.
/*
 * 화면 동작
 *  - 진입하면 운용사 콤보 목록을 받는다. [종목 찾기](ULDSTF92017)로 PF 종목을 고르면 종목명변경 내역을 조회한다.
 *  - [조회]는 종목을 골랐을 때만, 운용사는 선택 조건이다.
 *  - 목록 더블클릭은 종목명변경 관리 팝업(ULDSTF05317)을 이력(H)으로, [신규]는 신규(N)로 연다.
 *    팝업이 저장했다고 돌려주거나 X 로 닫히면 목록을 다시 조회한다(pf 계약서 §2).
 *  - [양식 다운로드]는 업로드 양식 파일을, [일괄 업로드]는 엑셀 일괄업로드 팝업(ULDSTF05360)을 연다.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF09316/ULDSTF09316.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09316.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 증권그룹 → 운용사 콤보 목록 → 사용자 시장별 영문심볼 열 → 조회 영역 Enter 키 바인딩. 초기 조회는 없다. (원본 init — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 증권그룹 — 개발 사본은 문자열 "PF" 고정
    scwin.secugrpId = $c.lc.getGlbValue("SECUGRP_ID_PF");

    // 2) 운용사 콤보 목록 (원본 fn_get_isurcode) — 콤보는 itemset 으로 바인딩돼 있다(개발 사본 setNodeSet)
    await scwin.selectTrstComList();

    // 3) 사용자 시장별 영문종목심볼 열 (원본 fn_setComponentSymbl)
    scwin.setComponentSymbl(String($c.session.getUserInfo("market") ?? ""));

    // 4) 조회 영역 Enter 키(규칙 22)
    $c.win.setEnterKeyEvent(panel_Top, scwin.btn_Search_onclick);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_FindIsu_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 찾기(돋보기) 버튼 클릭 — 고르면 목록을 조회한다. (원본 img_ISU_CD onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_FindIsu_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09316.btn_FindIsu_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 버튼 클릭 — 종목을 골랐는지 확인하고 조회한다. (원본 btn_Search onclick + fn_all_list_sync — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        if (!await scwin.validateSearch("종목코드를 선택바랍니다")) return;
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09316.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_List_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 목록 더블클릭 — 그 건으로 종목명변경 관리 팝업을 이력(H)으로 연다. (원본 grd_List oncelldblclick + fn_OpenDetailMng — §4)
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 열 id
 * @returns
 * @hidden N
 */
scwin.grd_List_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.openDetail(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09316.grd_List_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.btn_New_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 버튼 클릭 — 종목을 골랐으면 종목명변경 관리 팝업을 신규(N)로 연다. (원본 btn_New onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_New_onclick = async function (e) {
    try {
        await scwin.writeNew();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09316.btn_New_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Excel_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 엑셀다운로드 버튼 클릭. (원본 btn_Excel_3 onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Excel_onclick = async function (e) {
    try {
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09316.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_FormDown_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 양식 다운로드 버튼 클릭 — 일괄업로드 양식 파일을 내려받는다. (원본 btn_FORM_U1 onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_FormDown_onclick = async function (e) {
    try {
        await scwin.downloadTemplate();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09316.btn_FormDown_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Upload_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 일괄 업로드 버튼 클릭 — 엑셀 일괄업로드 팝업을 연다. (원본 btn_trigger1 onclick = btn_excelUpload_onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Upload_onclick = async function (e) {
    try {
        await scwin.openUploadPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09316.btn_Upload_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectTrstComList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 운용사 콤보 목록 조회 → dlt_trstCom. (원본 fn_get_isurcode — §5.1)
 * @returns
 * @hidden N
 */
scwin.selectTrstComList = async function () {
    const sbmOptions = {
        id : "sbm_selectTrstComList",
        method : "get",
        action : "/api/listing/lstmgt/corpchrg/select-list-isurcode",
        target : "dlt_trstCom=body.listEtfTrstComLP",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀
};

/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목명변경 내역 조회 → dlt_list. 요청은 종목코드·운용사(발행기관코드). (원본 fn_list_sync — §5.2)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectList = async function () {
    const sbmOptions = {
        id : "sbm_selectList",
        method : "get",
        action : "/api/listing/lstproc/pf/isunmchg/select-list",
        target : "dlt_list=body",
        gridview : "grd_List",
        isProcessMsg : false
    };

    const requestData = {
        isuCd : dma_search.get("isuCd"),
        isurCd : dma_search.get("trstComIsurCd")    // 운용사 — 「전체」면 빈 값
    };
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return false;      // 진행 중 조회가 있어 이번 호출은 건너뜀
    return result?.responseJSON?.success === true;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.setComponentSymbl
 * @author Inswave
 * @date 2026. 10. 30
 * @description 사용자 시장이 코스닥(2)이면 영문종목심볼 열을 숨긴다. (원본 fn_setComponentSymbl — §6.1)
 * @param {String} mktId 사용자 시장구분
 * @returns
 * @hidden N
 */
scwin.setComponentSymbl = function (mktId) {
    if (mktId === scwin.SYMBL_HIDE_MKT) {
        grd_List.setColumnVisible("isuEngSymbl", false);
    }
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 찾기(ULDSTF92017) — 고른 종목·발행기관을 담고 목록을 조회한다. 취소·닫기면 아무것도 하지 않는다.
 * (원본 img_ISU_CD onclick — 92017 을 직접 열던 것을 pcc popFindIsu 로, §6.2)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    const result = await $c.lc.popFindIsu(scwin.secugrpId);
    // 취소·닫기(X)도 { isCloseButtonClick } 객체가 온다 → 종목코드로 판정(개발 사본 isEmpty(result) 는 늘 거짓)
    if (result?.isCloseButtonClick === true || $c.util.isEmpty(result?.isuCd)) return;

    dma_search.set("isuCd", result.isuCd);
    dma_search.set("isuNm", result.isuKorNm ?? "");
    scwin.isurCd = String(result.isurCd ?? "");

    await scwin.search();
};

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 — 목록·건수를 비우고 조회한 뒤 건수를 적는다. (원본 fn_list_sync — §6.3)
 * @returns
 * @hidden N
 */
scwin.search = async function () {
    dlt_list.removeAll();
    tbx_totCnt.setValue("0");

    if (!await scwin.selectList()) return;

    tbx_totCnt.setValue(dlt_list.getRowCount());
};

/**
 * @method
 * @name scwin.validateSearch
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목을 골랐는지 확인한다 — 고르지 않았으면 안내하고 종목코드에 포커스한다. (원본 fn_all_list_sync·btn_New onclick — §6.4)
 * @param {String} message 안내 문구 (원본이 조회·신규에서 서로 다르게 썼다)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.validateSearch = async function (message) {
    if (!$c.util.isEmpty(dma_search.get("isuCd"))) return true;

    await $c.win.alert(message);
    txb_ISU_CD.focus();
    return false;
};

/**
 * @method
 * @name scwin.writeNew
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 — 종목을 확인하고 종목명변경 관리 팝업을 신규(N)로 연다. (원본 btn_New onclick + fn_OpenPopup — §6.5)
 * @returns
 * @hidden N
 */
scwin.writeNew = async function () {
    if (!await scwin.validateSearch("[종목]을 선택하세요.")) return;

    await scwin.openMngPopup({
        openTyp : scwin.OPEN_TYP_NEW,
        bzProcsNo : "",
        isurCd : scwin.isurCd,
        secugrpId : scwin.secugrpId,
        isuCd : dma_search.get("isuCd"),
        pageId : scwin.PAGE_ID,
        chgListMktactAdmNo : ""     // 개발 사본은 앞서 더블클릭한 행의 값을 그대로 넘겼다(§8 #4)
    });
};

/**
 * @method
 * @name scwin.openDetail
 * @author Inswave
 * @date 2026. 10. 30
 * @description 이력 — 더블클릭한 행의 업무처리번호·발행기관·변경상장시장조치관리번호로 종목명변경 관리 팝업을 이력(H)으로 연다.
 * (원본 fn_OpenDetailMng + fn_setBzProcsNo — §6.6)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @returns
 * @hidden N
 */
scwin.openDetail = async function (rowIndex) {
    if (rowIndex < 0) return;

    await scwin.openMngPopup({
        openTyp : scwin.OPEN_TYP_HIST,
        bzProcsNo : String(dlt_list.getCellData(rowIndex, "bzProcsNo") ?? ""),
        isurCd : String(dlt_list.getCellData(rowIndex, "isurCd") ?? ""),
        secugrpId : scwin.secugrpId,
        isuCd : dma_search.get("isuCd"),
        pageId : scwin.PAGE_ID,
        chgListMktactAdmNo : String(dlt_list.getCellData(rowIndex, "chgListMktactAdmNo") ?? "")
    });
};

/**
 * @method
 * @name scwin.openMngPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목명변경 관리 팝업(ULDSTF05317)을 data 로 열고 닫힐 때까지 기다린다. 저장했다고 돌려주거나 X 로 닫히면 목록을 다시 조회한다.
 * (원본 fn_OpenPopup — §6.7)
 * @param {Object} data 넘길 data — { openTyp, bzProcsNo, isurCd, secugrpId, isuCd, pageId, chgListMktactAdmNo }
 * @returns
 * @hidden N
 */
scwin.openMngPopup = async function (data) {
    const options = {
        id : "ULDSTF05317",
        popupName : "종목명변경 관리",
        width : 1230,
        height : 500,
        type : "pageFramePopup"
    };

    // TODO: ULDSTF05317 은 저장소에 없다 — data 키(평면, 개발 사본의 { pData : … } 래핑·v 접두 키 정리)·반환 { isSaved } 는 제안이다 (§10 #1)
    const result = await $c.win.openPopup(scwin.MNG_POPUP_URL, options, data);

    // 개발 사본은 반환을 받고 아무것도 하지 않았다 — 공통 재조회 규약(pf 계약서 §2)
    if (result?.isSaved === true || result?.isCloseButtonClick === true) {
        await scwin.search();
    }
};

/**
 * @method
 * @name scwin.openUploadPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 엑셀 일괄업로드 팝업(ULDSTF05360)을 열고 닫힐 때까지 기다린다. 원본처럼 닫힌 뒤 다시 조회하지 않는다. (원본 fn_openUpload — §6.8)
 * @returns
 * @hidden N
 */
scwin.openUploadPopup = async function () {
    const options = {
        id : "ULDSTF05360",
        popupName : "종목변경 엑셀일괄업로드",
        width : 1300,
        height : 750,
        type : "pageFramePopup"
    };

    // TODO: ULDSTF05360 은 저장소에 없다 — data 키는 제안(개발 사본 'pageId '(뒤 공백)·vIsurCd 정정), 업로드 뒤 재조회 여부 확인 (§10 #2)
    await $c.win.openPopup(scwin.UPLOAD_POPUP_URL, options, { pageId : scwin.PAGE_ID, isurCd : scwin.isurCd });
};

/**
 * @method
 * @name scwin.downloadTemplate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 일괄업로드 양식 파일을 내려받는다. (원본 btn_FORM_U1 onclick — §6.9)
 * @returns
 * @hidden N
 */
scwin.downloadTemplate = async function () {
    await $c.data.downFile("/api/listing/lstproc/pf/isunmchg/template-download", "etf_isu_nm_change_sample.xlsx");
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 30
 * @description 목록을 엑셀로 내려받는다. 0건 안내는 공통 함수가 한다. (원본 btn_Excel_3 onclick — §6.10)
 * @returns
 * @hidden N
 */
scwin.excelDown = async function () {
    await $c.data.downloadGridViewExcel(grd_List, {
        // 파일명 {menuId}_{이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42) — 개발 사본은 "ULDSTF09316_종목변경_" + 시각
        fileName : $c.win.getProgramId() + "_종목변경_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx",
        sheetName : "리스트"
    });
};
